package main
import("encoding/json";"os";"strings")
type input struct{Valid bool; HasTx bool; BeginOK bool; ApplyResult string; CommitOK bool}
type graderTransactionMedium struct{beginOK bool; applyResult string; commitOK bool; events *[]string}
func(t *graderTransactionMedium) Begin()bool{*t.events=append(*t.events,"begin");return t.beginOK}
func(t *graderTransactionMedium) Apply()string{*t.events=append(*t.events,"apply");return t.applyResult}
func(t *graderTransactionMedium) Commit()bool{*t.events=append(*t.events,"commit");return t.commitOK}
func(t *graderTransactionMedium) Rollback(){*t.events=append(*t.events,"rollback")}
func expected(x input)string{if !x.Valid||!x.HasTx{return ""};if !x.BeginOK{return "begin"};if x.ApplyResult!="ok"{return "begin,apply,rollback"};if !x.CommitOK{return "begin,apply,commit,rollback"};return "begin,apply,commit"}
